import {course} from './build.js';

// Original analytical instruction, not a substitute, reconstruction or synopsis
// of the five copyrighted books. No invented passage is attributed to an author.
const RULES=['HOSA Medical Reading: official 2026–27 reading list and test plan','https://hosa.org/wp-content/uploads/2026/08/MR-26-27.pdf'];
const BOOKS=[
 {title:'Crisis Averted: The Hidden Science of Fighting Outbreaks',author:'Caitlin Rivers',source:['Penguin Random House: Crisis Averted','https://www.penguinrandomhouse.com/books/704843/crisis-averted-by-caitlin-rivers-phd/'],orientation:'The publisher presents this book as an account of public-health work and outbreak prevention. Use your assigned copy to establish the author’s particular examples, reasoning and conclusions.'},
 {title:'Everything Is Tuberculosis: The History and Persistence of Our Deadliest Infection',author:'John Green',source:['Penguin Random House: Everything Is Tuberculosis','https://penguinrandomhouselibrary.com/book/?isbn=9780525556572'],orientation:'The publisher identifies a patient narrative connected with scientific and social histories of tuberculosis. The lessons below practice analyzing that combination; they do not retell the patient’s story.'},
 {title:'Fragmented: A Doctor’s Quest to Piece Together American Health Care',author:'Ilana Yurkiewicz',source:['Ilana Yurkiewicz: Fragmented','https://ilanayurkiewicz.com/book'],orientation:'The author’s official description connects gaps in patient information and continuity with wider problems in health care. Read the assigned text for her specific cases, explanations and proposed responses.'},
 {title:'The Next Patient: The Incredible World of Emergency Medicine',author:'J. Thomas Grant',source:RULES,orientation:'HOSA identifies this emergency-medicine book as an assigned reference. Full text was not available for this course. These are original exercises in reading emergency narratives, not claims about particular chapters or patients in Grant’s book.'},
 {title:'Grit: The Power of Passion and Perseverance',author:'Angela Duckworth',source:['Simon & Schuster: Grit','https://www.simonandschuster.com/books/Grit/Angela-Duckworth/9781501111112/'],orientation:'The publisher identifies passion and perseverance as the book’s central construct. Read the assigned book to evaluate how Duckworth develops and supports that idea; these exercises do not reproduce her scale or chapter content.'}
];
const q=(p,a,b,c,d,why)=>[p,[a,b,c,d],why];
const sort=(title,buckets,items)=>({t:'w',kind:'sort',title,buckets,items});
const match=(title,pairs)=>({t:'w',kind:'match',title,pairs});
const order=(title,steps)=>({t:'w',kind:'order',title,steps});
const lessons=[];
function add(book,entry){
 entry.sections.unshift(['Assigned-book connection and an original practice passage',[
  `**Assigned reading: ${BOOKS[book].title}, by ${BOOKS[book].author}.** ${BOOKS[book].orientation} Keep notes from the actual book separate from the invented exercise below. Names, numbers, events and decisions in the exercise are original Valus teaching material and are not details to memorize as facts about the assigned book.`,
  {t:'callout',kind:'remember',text:'Original Valus practice passage — fictional, not an excerpt or paraphrase from the assigned book.'},entry.passage
 ]]);
 delete entry.passage;
 entry.sources=[RULES,BOOKS[book].source,...(entry.sources||[])];
 if(book===3)entry.sources.push(['Google Books: bibliographic record for The Next Patient (publisher metadata only)','https://books.google.com/books/about/The_Next_Patient.html?id=LkjzzwEACAAJ']);
 lessons.push(entry);
}

add(0,{
title:'Crisis Averted: read prevention claims and invisible outcomes',
hook:'When an outbreak does not grow, did prevention work, was the threat smaller than expected, or did several things change together? Reading a prevention narrative requires examining what happened and what comparison supports the conclusion.',
objectives:['Distinguish an observed result from an inferred prevention effect.','Identify the counterfactual behind an outbreak-prevention claim.','Read numbers with their denominators and time windows.','Build an evidence ledger from the assigned book without importing fictional details.'],
passage:'A fictional coastal town received seven reports of stomach illness after a weekend festival. The local team interviewed attendees, inspected shared facilities and issued a precautionary notice while laboratory results were pending. Ten days later, the total stood at eleven reported illnesses. A council member said the notice had prevented hundreds of cases. The investigator replied that the final count was useful but did not show exactly what would have happened without the notice. Attendance had been lower than expected, and reporting was incomplete. The team documented which actions occurred, when they occurred and what information had been available at each decision. It recommended faster reporting and a clearer contact list before the next festival.',
sections:[
['Separate the result from the causal claim',[
'The passage provides an observed count and a statement about cases supposedly prevented. These are different kinds of information. Eleven reported illnesses is an observation within the fictional reporting system. Hundreds of prevented cases is a causal estimate requiring additional support. The latter cannot be obtained merely by subtracting eleven from an unspecified expectation. Ask where the expectation came from, which population it describes and whether the observation period is comparable. A vivid claim may express confidence or advocacy without supplying the evidence needed to quantify an effect.',
'The **counterfactual** is the outcome that would have occurred without the action. It cannot be directly observed for the same town at the same time, so investigators need a justified comparison or model. A comparison may involve similar settings, earlier periods or assumptions about transmission, each with limitations. Your reading task is not to reject all prevention claims because uncertainty exists. It is to distinguish a plausible mechanism, an observed association and a well-supported effect estimate. Mark which level the author actually claims before evaluating whether the evidence reaches it.'
]],
['Read the denominator, clock and reporting process',[
'An illness count becomes more interpretable when you know the number of people exposed and how cases were identified. Seven reports among a small gathering and seven reports among a large gathering describe different proportions. The relevant denominator must correspond to the numerator: festival attendees, town residents and people who sought care are not interchangeable populations. Also distinguish the time of exposure, symptom onset, report and intervention. A report arriving after a notice does not prove that the illness began after the notice.',
'Reported cases are not necessarily all cases. People may not seek care, a reporting definition may change or a team may intensify its search. A larger reported count can therefore reflect improved detection as well as increased illness. Conversely, a small count may reflect incomplete observation. In the invented passage, incomplete reporting is explicitly acknowledged, so a confident claim that the team found every case would contradict the available information. A careful reader preserves that qualifier in a summary instead of stripping it away to create a cleaner story.'
]],
['Recognize action under uncertainty',[
'Decisions often occur before all evidence is available. Evaluate a decision using the information and options available at that time, while evaluating the outcome with later evidence. This distinction reduces hindsight bias. If later laboratory results clarify an event, they do not automatically prove that a reasonable earlier precaution was foolish. Equally, a favorable outcome does not establish that every earlier choice was justified. Ask what risks were considered, how reversible the action was and whether the response was proportionate to the uncertainty described.',
'The fictional team records a timeline and recommends faster reporting. This is a learning claim, not proof that the notice alone caused the limited outbreak. Identify the verb carefully: documenting, estimating, recommending and demonstrating describe different activities. When reading Rivers’s actual text, record the author’s verbs and the evidence attached to them. Then write a short paraphrase that maintains the strength of the claim. Replacing “may have contributed” with “definitely prevented” changes the meaning even if the rest of the sentence sounds similar.'
]],
['Transfer the method to the assigned reading',[
'Choose one prevention discussion from your own copy of Crisis Averted. Record the chapter or location, the problem, the action, the observed result and the comparison supporting any effect claim. Add one column for uncertainty that the author acknowledges and another for questions you still have. Use a short quotation only when exact wording matters; otherwise write an original concise note and retain the location. Do not fill a missing number or mechanism with the invented festival example. A blank marked “not stated here” is more accurate than a confident guess.',
'Turn the ledger into two questions: one asks what the text explicitly reports, and one asks what conclusion the evidence supports. Draft plausible distractors by changing the denominator, reversing the sequence or overstating certainty. Verify the correct answer against the book before using the questions for exam practice. This process builds knowledge of the assigned text while practicing analysis. Completing this companion lesson only demonstrates the analytical skill; the official event can still ask about names, examples and details that require reading the book itself.',
sort('Classify statements from the fictional outbreak',['Reported observation','Inference requiring more evidence','Proposed improvement'],[['Eleven illnesses were reported by day ten.',0],['The notice prevented exactly hundreds of cases.',1],['Create a clearer contact list before the next festival.',2],['Attendance was lower than expected.',0],['The notice alone caused the final count.',1]]),
{t:'w',kind:'evidencebench',title:'Practice matching a claim with adequate evidence'}
]]],
takeaways:['An observed count is not automatically an effect estimate.','Keep denominators, time windows and reporting limits attached to numbers.','The actual assigned book remains the source for its events and details.'],terms:[['Counterfactual','The outcome that would have occurred under a different action or condition.'],['Hindsight bias','Judging an earlier decision as though later information was already available.']],
mcqs:[q('In the invented passage, which is directly reported?','Eleven illnesses by day ten','Exactly hundreds of cases prevented','Every attendee was interviewed','The notice was the only change','The count is stated; the other claims exceed the passage.'),q('What is missing from the council member’s numerical claim?','A justified estimate of what would have happened without the notice','A more dramatic adjective','The investigator’s favorite method','A longer title','Prevention effects require a comparison or counterfactual.'),q('Which denominator would fit an attack proportion among attendees?','The number of festival attendees in the defined population','All residents of the country','Only the eleven reported cases','The number of council members','Numerator and denominator must describe the same population.'),q('Why can more reports occur without more true illness?','Detection or reporting may improve','Reports always equal all infections','Denominators never matter','Every new report proves transmission increased','Observation processes affect recorded counts.'),q('How should an earlier decision be assessed?','Using the information and options available when it was made','As if all later results were already known','Only by whether the result was favorable','Only by the most confident speaker','This avoids hindsight and outcome bias.'),q('Which summary preserves uncertainty?','The notice may have contributed, but its exact effect was not established','The notice certainly prevented hundreds','The team proved no cases were missed','No action could possibly matter','The qualified statement matches the available evidence.'),q('What should a reading ledger do when a number is absent?','Mark it as unstated at that location','Borrow the festival number','Estimate and label it as the author’s fact','Delete the entire topic','A study guide must not invent book details.'),q('What does completing this lesson demonstrate?','Practice analyzing prevention claims','Complete knowledge of every assigned-book detail','Access to the full book','An official HOSA score','The original exercise cannot replace reading the assigned text.')],
frq:{prompt:'Using the fictional festival passage, evaluate the claim that the notice prevented hundreds of cases. Distinguish the observation, missing comparison and one useful next step.',rubric:[['Identify the observed result',['eleven','reported','count']],['Explain the counterfactual gap',['without','comparison','estimate']],['Propose useful evidence',['timeline','reporting','population']]],model:'The passage reports eleven illnesses by day ten, but it does not provide a defensible estimate of illnesses without the notice. Lower attendance and incomplete reporting complicate interpretation. A timeline of exposure, onset, reports and actions, together with a defined exposed population and a justified comparison, would help evaluate the claim. The result may be consistent with useful prevention, but it does not establish the council member’s precise numerical assertion.'}
});

add(0,{
title:'Crisis Averted: institutions, communication and preparedness',
hook:'A response can contain sound scientific advice and still fail if nobody knows who will carry it out. This lesson studies the connection between evidence, responsibilities and public communication through an original scenario.',
objectives:['Distinguish scientific uncertainty from an operational coordination failure.','Trace a preparedness recommendation to its proposed mechanism.','Evaluate communication for accuracy, clarity and feasibility.','Construct text-grounded comparison notes from Crisis Averted.'],
passage:'In an invented district, a laboratory sent an unusual result to three offices. Each office believed another would contact the school involved. Two days passed before a nurse asked who owned the follow-up. A manager proposed a new dashboard. Another employee suggested a named recipient, a confirmation step and a backup person for absences. At the public meeting, the director explained what was known, what remained uncertain and when another update would be issued. A resident said the instructions assumed access to a car. The director revised the plan to include a local collection point and asked staff to confirm whether residents could use it. No outcome data had yet been collected.',
sections:[
['Identify the kind of problem before evaluating a solution',[
'The unusual laboratory result represents information, but the passage’s immediate operational problem is unassigned responsibility. Three offices received a message, yet none confirmed ownership of the next action. A new display might improve visibility without solving that gap. Distinguish information availability, interpretation, accountability and execution. A proposal is stronger when it explains which link it changes. “Improve technology” is a broad aspiration; “send the result to a named recipient who confirms receipt and has a backup” specifies a process that can be observed.',
'This distinction helps when reading public-health narratives. A scientific uncertainty might concern what an organism is doing or how an exposure occurred. An operational uncertainty might concern who will act, what resource is available or whether instructions reached the intended audience. They can interact, but they require different evidence. Do not treat a coordination failure as proof that the underlying science is wrong. Equally, do not assume accurate scientific advice guarantees successful implementation. The passage gives enough information to identify the ownership gap but not enough to measure the proposed solution’s effect.'
]],
['Map the recommendation and its assumptions',[
'A recommendation can be represented as a chain: proposed action, immediate change, intermediate result and desired outcome. Naming a recipient may improve acknowledgement; acknowledgement may speed follow-up; faster follow-up may reduce avoidable delay. Each arrow is an assumption to examine. The existence of a name on a roster does not prove the person has time, authority or access to the required information. A backup system also needs a trigger that tells the backup when to act. Reading the chain makes vague recommendations more concrete.',
'Separate the author’s recommendation from your own extension. In a notebook, label one column “the text proposes” and another “my application.” Otherwise, a practical idea generated during study can later be misremembered as something the author said. This matters in a book-based test: the best real-world solution is not necessarily the answer to a question asking which solution appears in the assigned passage. Begin by identifying what the question asks you to retrieve, then evaluate or apply only when the prompt calls for that additional step.'
]],
['Communicate uncertainty without empty reassurance',[
'The fictional director separates known information, unresolved questions and the next update. This structure can be clear without pretending that every answer is available. Precision includes explaining the uncertainty’s scope. “We do not yet know the source” differs from “we know nothing.” A statement can also acknowledge change: a later update may revise an earlier estimate because new evidence arrived. Evaluate whether the explanation identifies the reason for revision rather than treating every change as inconsistency or every confident statement as reliability.',
'Communication also depends on whether a person can act on it. Instructions that assume a car exclude residents without one. The collection point addresses a specific access barrier, but the team still needs to check usability. Distance, opening hours, language and trust may create additional obstacles. A reader should avoid jumping from a revised plan to a proven successful outcome. The last sentence explicitly states that outcome data are unavailable. Preserve this limit when writing a summary or selecting an answer about effectiveness.'
]],
['Build a preparedness comparison from the book',[
'In your copy of Crisis Averted, select two passages about preparation or response. They need not describe the same kind of event. Record the setting, institutional actors, information available, decisions and consequences. Compare a common dimension such as reporting, responsibility, public communication or resource access. A valid comparison states both the similarity and a relevant difference. Two passages can illustrate communication problems without supporting the claim that every institution failed in the same way or that one policy would fit both settings.',
'Write an original synthesis of about one paragraph using location references for both passages. Use precise verbs: the author describes, attributes, questions or recommends. If the author supplies evidence for a mechanism, name it. If you are proposing a connection, mark it as your interpretation. Then check whether your synthesis would remain accurate if a reader opened the cited locations. This verification step prevents thematic enthusiasm from replacing close reading. For exam preparation, retain the actual book’s people and examples in a separate retrieval set; the fictional district is only a training case.',
order('Build a closed follow-up loop',['Define the action and the responsible recipient','Transmit the necessary information','Confirm receipt and understanding','Complete or escalate the action','Document closure and review unresolved items']),
sort('Separate what the fictional passage establishes',['Stated in the passage','Reasonable proposal, not proven outcome','Unsupported conclusion'],[['Each office expected another to act.',0],['A named recipient could reduce ambiguity.',1],['The dashboard alone eliminated every delay.',2],['A resident lacked the assumed transport access.',0],['The revised plan has already improved health outcomes.',2]])
]]],
takeaways:['Diagnose the process gap before choosing a solution.','Separate recommendations from evidence of results.','Communication is incomplete when people cannot use the instructions.'],terms:[['Accountability','Clear ownership of an action and its follow-up.'],['Implementation assumption','A condition that must hold for a proposed action to produce its intended effect.']],
mcqs:[q('What immediate problem does the invented district reveal?','No office confirmed responsibility for follow-up','No result existed','The school refused every call','All staff lacked scientific training','The passage explicitly describes an ownership gap.'),q('Why might a dashboard be insufficient?','Visibility does not automatically assign responsibility','Dashboards can never display information','Only paper can support communication','The result was already proven false','The proposed tool must address the actual mechanism.'),q('Which is an operational question?','Who confirms and completes the follow-up?','What is the organism’s genome?','What is the biological mechanism?','Which laboratory assay is most sensitive?','Ownership and execution are operational concerns.'),q('What does the resident’s comment expose?','An access assumption in the instructions','Proof that the science is false','Proof that no resident has transport','A final outcome measurement','The plan assumed a resource not everyone had.'),q('Which claim is unsupported by the passage?','The revised plan already improved health outcomes','A collection point was proposed','An update was promised','Three offices received a result','Outcome data had not yet been collected.'),q('How should a student distinguish an author’s proposal from a personal idea?','Label them separately in the reading ledger','Combine them without attribution','Attribute every useful idea to the author','Avoid all personal interpretation','Separate labeling prevents false recall.'),q('Which update communicates uncertainty precisely?','The source remains uncertain; the next update will explain new findings','We know nothing and can say nothing','Everything is safe because we are confident','Any revised estimate means all earlier work was invalid','Specific uncertainty is more informative than blanket statements.'),q('What makes a cross-passage comparison defensible?','A common dimension with evidence and relevant differences','Identical conclusions imposed on both passages','One quotation with no context','A claim based only on titles','Comparison requires textual support and attention to context.')],
frq:{prompt:'Evaluate the two proposed fixes in the fictional district and explain why no outcome conclusion is yet justified.',rubric:[['Identify accountability gap',['responsibility','recipient','ownership']],['Connect proposal to mechanism',['confirm','backup','follow']],['Preserve outcome uncertainty',['no','data','outcome']]],model:'The core gap is that no office accepted ownership of follow-up. A dashboard may improve visibility but does not necessarily assign responsibility. A named recipient, confirmation step and backup more directly address that mechanism, provided the people have authority and capacity to act. The transport revision addresses another implementation barrier. Because no outcome data have been collected, neither proposal can yet be described as a proven health improvement.'}
});

import {READING_B} from './medical-reading-b.js';
import {READING_C} from './medical-reading-c.js';
for(const [book,entry] of [...READING_B,...READING_C])add(book,entry);

export default course('Medical Reading',{intro:'Companion analysis for the five HOSA 2026–27 assigned books. Full books were not available for authoring, so this course does not supply chapter summaries, invented book facts or a replacement for reading. Publisher and author pages establish the reading map; all practice passages are explicitly original fiction, and background sections draw on public health and research sources rather than the books. Read each complete assigned book and verify details in your own copy. The official test allocates ten questions to each book; local FRQs are learning checkpoints, not official HOSA scoring.',units:[
 {title:'Crisis Averted · prevention and public systems',summary:'Analyze evidence and preparedness alongside the assigned Rivers book.',lessons:lessons.slice(0,2)},
 {title:'Everything Is Tuberculosis · science, history and inequality',summary:'TB background from CDC and WHO, braided narratives and arguments about why a curable disease persists.',lessons:lessons.slice(2,4)},
 {title:'Fragmented · continuity and coordination',summary:'Handoffs, missing information and evaluating a clinician-author’s argument for change.',lessons:lessons.slice(4,6)},
 {title:'The Next Patient · emergency medicine',summary:'Triage, time and sequence, diagnostic uncertainty and the people behind emergency care.',lessons:lessons.slice(6,8)},
 {title:'Grit · evidence, practice and putting it together',summary:'Evaluating a psychological concept, study strategies and cross-book synthesis for the essay tiebreaker.',lessons:lessons.slice(8,10)},
]});
